import json  # Imports the json module for JSON parsing.
from functools import reduce  # For merging DataFrames iteratively in the main function
from typing import Dict, List, Optional  # type hints for better code readability
import re  # Imports the regular expression module for text processing.
import pandas as pd  # for DataFrame creation and data manipulation.
import requests  # This library for making HTTP requests to the World Bank API.
from requests.exceptions import HTTPError, RequestException, Timeout, ConnectionError  # Imports specific exception classes for handling HTTP, request, timeout, and connection errors.
import time  # Imports the time module for adding delays during retry attempts for rate limiting.
INDICATORS = {  # Defines a dictionary mapping human-readable indicator names to World Bank API codes.
    "population": "SP.POP.TOTL",  # Maps "population" to the API code for total population.
    "growth_rate": "SP.POP.GROW",  # Maps "growth_rate" to the API code for population growth rate
    "area": "AG.LND.TOTL.K2",  # Maps "area" to the API code for total land area in square kilometers.
    "density": "EN.POP.DNST",  # Maps "density" to the API code for population density.
}  # Closes the INDICATORS dictionary definition.
API_TEMPLATE = ("https://api.worldbank.org/v2/country/all/indicator/{indicator}""?format=json&MRV=1&per_page=20000")# Begins a string template for the World Bank API endpoint URL. It specifies the base URL for fetching indicator data for all countries and adds query parameters for JSON format, most recent value, and 20,000 results per page.Closes the API_TEMPLATE string definition.
def fetch_indicator(indicator_code: str, session: Optional[requests.Session] = None) -> pd.DataFrame:  # Defines a function to fetch an indicator’s data, with type hints for input and output.Documents the function’s purpose: fetching the most recent data as a DataFrame.
    url = API_TEMPLATE.format(indicator=indicator_code)  # Formats the API URL by inserting the indicator code into the template.
    sess = session or requests.Session()  # Uses the provided session or creates a new one for HTTP requests.
    max_retries = 3  # Sets the maximum number of retry attempts for handling rate limit errors.
    retry_delay = 5  # Defines a 5-second delay between retry attempts.
    for attempt in range(max_retries):  # Starts a loop to attempt the API request up to max_retries times.
        try:  # Begins a try block to handle potential HTTP or request errors
            r = sess.get(url, timeout=30)  # Sends a GET request to the API with a 30-second timeout.
            r.raise_for_status()  # Raises an HTTPError if the response status code indicates an error
            payload = r.json()  # Parses the JSON response into a Python dictionary.
            # More robust validation of the API response structure
            if not isinstance(payload, list) or len(payload) < 2: # Checks if 'payload' is NOT a list OR if it has fewer than 2 elements.The API is expected to return a list with at least 2 items (metadata and actual data).
                print(f"API response for {indicator_code} is not in the expected list format.")# Prints an error message indicating that the API response format is not what was expected.
                return pd.DataFrame(columns=["country", "value"])# Returns an empty pandas DataFrame with "country" and "value" as column names.
            metadata = payload[0]# Assigns the first element of the payload list to 'metadata'.This contains information like total records, pagination, or other meta info.
            data = payload[1]# Assigns the second element of the payload list to 'data'.This usually contains the actual dataset (rows of values per country).
            if data is None:# Checks if the 'data' part of the response is None (meaning no actual data was returned).
                print(f"API response for {indicator_code} contains no data.")# Prints an error message indicating that no data is available for this indicator.
                return pd.DataFrame(columns=["country", "value"])# Returns an empty DataFrame to keep the output structure consistent.
            if not isinstance(data, list):# Checks if the 'data' portion is NOT a list (which it should be if the API is returning multiple rows).
                 print(f"API response data for {indicator_code} is not in the expected list format.")# Prints an error message indicating that the data structure was not as expected.
                 return pd.DataFrame(columns=["country", "value"])# Returns an empty DataFrame with the expected column names.
            rows = []  # Initializes an empty list to store parsed data rows.
            for rec in data:  # Loops through the data entries in the second element of the JSON payload.
                # More robust handling of missing keys in the data records
                country_info = rec.get("country", {})#Retrieves the value associated with the "country" key from the 'rec' dictionary.If "country" is not present, it returns an empty dictionary as a default.
                country_name = country_info.get("value")# Extracts the "value" key from the 'country_info' dictionary. This typically contains the full country name (e.g., "Canada", "Ghana").
                iso3_code = rec.get("countryiso3code")# Retrieves the value of "countryiso3code" from the 'rec' dictionary.This is usually the 3-letter ISO code for the country (e.g., "CAN", "GHA").
                value = rec.get("value")#Retrieves the value of "value" from the 'rec' dictionary.This usually contains the main numerical or textual data point for the indicator being processed.
                if country_name and iso3_code and value is not None:
                    rows.append({ "country": country_name, "iso3": iso3_code,"value": value,})#Begins appending a dictionary to the rows list for each data entry.Opens a dictionary for a single row of country data and extracts the country code from the nested country dictionary, safely handling missing keys. Extracts the ISO3 country code, allowing for None if missing and also extracts the indicator value, allowing for None if missing.Closes the dictionary for the row and the append call for the row.
                else:
                    # Optional: Log or print a warning for records with missing essential data
                    print(f"Skipping record with missing data for indicator {indicator_code}: {rec}")#Prints a message indicating that the current record (rec) is being skipped because it has missing or incomplete data for the given 'indicator_code'.The record's full content is displayed to help with debugging.
            df = pd.DataFrame(rows)# Creates a pandas DataFrame from the list of rows.
            if df.empty:#Checks if the DataFrame 'df' contains no rows (i.e., it's empty).This means no valid data was collected or processed.
                 print(f"No valid data records found for indicator {indicator_code}.")#Prints a message indicating that no usable data was found for this specific indicator.
                 return pd.DataFrame(columns=["country", "value"])#Returns a new empty DataFrame with the expected columns ("country" and "value") to maintain a consistent output format for downstream processing.
            df = df.drop_duplicates(subset=["iso3"]).reset_index(drop=True)# Removes duplicate rows based on ISO3 code and resets the index.
            return df# Returns the processed DataFrame with the indicator data.
        except Timeout:# Catches a Timeout exception, which occurs when the request takes too long to get a response from the API.
            if attempt < max_retries - 1:#Checks if the current attempt number is less than the maximum allowed retries minus 1. This means there are still retry attempts left.
                print(f"Request timed out for {indicator_code}. Retrying in {retry_delay} seconds...")# Prints a message showing which indicator failed due to timeout and how long the program will wait before retrying.
                time.sleep(retry_delay)#Pauses execution for 'retry_delay' seconds before retrying the request.
                continue#Skips the rest of the loop body and starts the next retry attempt.
            else:#If there are no retry attempts left:
                print(f"Max retries reached for {indicator_code} (timeout). Returning empty DataFrame.")#Prints a message indicating that the maximum retry limit has been reached for this indicator.
                return pd.DataFrame(columns=["country", "value"])#Returns an empty DataFrame with the expected columns to maintain consistent output.
        except ConnectionError:## Catches a ConnectionError, which occurs if there is a network issue or the API server cannot be reached.
             if attempt < max_retries - 1:#Checks if there are still retry attempts remaining.
                print(f"Connection error for {indicator_code}. Retrying in {retry_delay} seconds...")#Prints a message indicating a connection issue and the delay before the next retry.
                time.sleep(retry_delay)#Waits for the specified retry delay before retrying.
                continue#Moves to the next retry attempt.
             else:#If no retry attempts are left:
                print(f"Max retries reached for {indicator_code} (connection error). Returning empty DataFrame.")#Prints a message that the maximum retries have been reached for this indicator.
                return pd.DataFrame(columns=["country", "value"])#Returns an empty DataFrame with "country" and "value" columns for consistent output.
        except HTTPError as e:  # Catches HTTP errors raised by raise_for_status().
            if r.status_code == 429:  # Checks if the error is a 429 (Too Many Requests) status code for rate limiting.
                if attempt < max_retries - 1:  # Ensures there are retries left before proceeding.
                    print(f"Rate limit exceeded for {indicator_code}. Retrying in {retry_delay} seconds...")  # Prints a message indicating a retry attempt for rate limiting.
                    time.sleep(retry_delay)  # Pauses execution for the specified delay to respect rate limits.
                    continue  # Continues to the next loop iteration to retry the request.
                else:  # Handles the case where maximum retries are exhausted.
                    print(f"Max retries reached for {indicator_code} (status 429). Returning empty DataFrame.")  # Notifies that retries failed and an empty DataFrame will be returned.
                    return pd.DataFrame(columns=["country", "value"])  # Returns an empty DataFrame for failed 429 errors.
            else:  # Handles other HTTP errors (e.g., 404 for invalid endpoint).
                print(f"HTTP error for {indicator_code}: {r.status_code}. Returning empty DataFrame.")  # Notifies of the specific HTTP error and status code.
                return pd.DataFrame(columns=["country", "value"])  # Returns an empty DataFrame for other HTTP errors.
        except RequestException as e:  # Catches general request exceptions (e.g., network issues, timeouts).
            print(f"Request failed for {indicator_code}: {e}. Returning empty DataFrame.")  # Notifies of the request failure with the error message.
            return pd.DataFrame(columns=["country", "value"])  # Returns an empty DataFrame for request failures.
        except json.JSONDecodeError:# Handles the specific error that occurs if the JSON response is not valid or cannot be parsed
            print(f"Failed to decode JSON response for {indicator_code}. Returning empty DataFrame.")# Prints an error message indicating which indicator failed and that an empty DataFrame will be returned.
            return pd.DataFrame(columns=["country", "value"])# Returns an empty pandas DataFrame with predefined column names "country" and "value"
        except Exception as e:# Catches any other type of unexpected error that wasn't handled by the previous except block
            print(f"An unexpected error occurred for {indicator_code}: {e}. Returning empty DataFrame.")# Prints a generic error message with the indicator code and the actual exception message (e).
            return pd.DataFrame(columns=["country", "value"])# Returns an empty pandas DataFrame with the same predefined column names
def main(out_path: str, limit: Optional[
    int] = None):  # Defines the main function to orchestrate data fetching and saving, with optional row limit.
    session = requests.Session()  # Creates a session for reusing HTTP connections across requests.
    dfs: List[pd.DataFrame] = []  # Initializes an empty list to store DataFrames for each indicator.
    for field, code in INDICATORS.items():  # Iterates over the INDICATORS dictionary to fetch each indicator.
        print(f"Fetching {field} ({code}) ...")  # Prints a progress message for the current indicator being fetched.
        df = fetch_indicator(code, session=session)  # Calls fetch_indicator to retrieve data for the current indicator.
        if not df.empty: # Check if the fetched DataFrame is not empty before renaming and appending
            df = df.rename(columns={"value": field})  # Renames the "value" column to the indicator’s human-readable name.
            dfs.append(df)  # Appends the DataFrame to the list of DataFrames.
        else:
            print(f"Skipping merge for {field} due to empty DataFrame.")#Prints a message indicating that the merge operation for the specified 'field' is being skipped because the DataFrame involved is empty, preventing further processing.
    # Merge on iso3 + country
    if not dfs: # Check if the list of DataFrames is empty before attempting to reduce
        print("No DataFrames to merge. Exiting.")#Prints a message indicating that there are no DataFrames available for merging, so the merge operation cannot proceed.
        return#Exits the current function immediately, stopping further execution.
    combined = reduce(lambda left, right: pd.merge(left, right, on=["iso3", "country"], how="outer"), dfs,) # Begins merging all DataFrames using reduce.Defines a merge function to combine DataFrames on ISO3 and country with an outer join. Specifies the list of DataFrames to merge and closes the reduce call to create a combined DataFrame.
    # Reorder and (optionally) limit rows
    cols = ["country", "population", "growth_rate", "area", "density"]  # Defines the desired column order for the final output.
    # Ensure all columns in 'cols' are present in 'combined' before reordering.
    present_cols = [col for col in cols if col in combined.columns]# Keep iso3 temporarily if it exists in the DataFrame
    combined = combined[["country", "iso3"] + [col for col in present_cols if col not in ["country", "iso3"]]] if "iso3" in combined.columns else combined[[col for col in present_cols if col != "country"]]#Reorders 'combined' DataFrame columns:If 'iso3' exists, place "country" and "iso3" first, then other columns excluding those two;else, include all columns from 'present_cols' except "country".
    combined = combined.sort_values("country").reset_index(drop=True)  # Sorts the DataFrame by country and resets the index.
    if limit:  # Checks if a row limit is specified.
        combined = combined.head(limit)  # Limits the DataFrame to the specified number of rows.
    # Ensure all columns in 'cols' are present in 'combined' before final column selection
    final_cols = [col for col in cols if col in combined.columns]# Creates a list 'final_cols' containing only those columns from 'cols'that actually exist in the 'combined' DataFrame's columns.This filters out any columns listed in 'cols' that are not present in 'combined'.
    combined = combined[final_cols]  # Select the final columns that are present.
    combined = combined.dropna()# Drop rows with any missing values.
    if combined.empty:# Checks if the 'combined' DataFrame has no rows
        print("Combined DataFrame is empty after dropping rows with missing values. Exiting.")# Prints a message indicating that after removing rows with missing data,the DataFrame is empty and further processing will stop.
        return#Exits the current function immediately to prevent further execution on an empty DataFrame.
    combined.to_csv(out_path, index=False, encoding="utf-8")  # Saves the DataFrame to a CSV file without the index, using UTF-8 encoding.
    print(f"Saved {len(combined)} rows to {out_path}")  # Prints a confirmation message with the number of rows saved.
    print(f"File '{out_path}' created successfully.") # Add this line to confirm file creation
main(out_path="worldbank_country_stats.csv",limit=None)  # Calls the main function to run the script, saving output to worldbank_country_stats.csv with no row limit.
