# Function to clean country names
def clean_country_name(name): #Defines a function clean_country_name to standardize country names in the dataset.The function takes a single argument name (a country name) and applies a series of cleaning steps to remove inconsistencies, such as quotes, commas, or regional qualifiers.
    if not isinstance(name, str): #Checks if the input name is a string; if not, returns it unchanged.
        return name #This handles cases where the country name might be missing to avoid errors in string operations. Non-string values are returned as-is.
    name = re.sub(r'^"|"$', '', name.strip()) #The re.sub function uses the regular expression r'^"|"$ to match a double quote (") at the start (^) or end ($) of the string. The strip() method removes leading/ending whitespace before applying the regex.
    # Replace commas and periods with spaces, remove qualifiers
    name = re.sub(r'[,.](?:\s*(The|Rep\.|RB|Islamic Rep\.|Dem\. Rep\.|People\'s Rep\.|Fed\. Sts\.|US))?$', '', name)#Removes commas or periods followed by specific trailing qualifiers (e.g., "The", "Rep.", "US") from the country name.The regex [,.] matches a comma or period. The (?:\s*(The|Rep\.|...))?$ part matches optional qualifiers at the end of the string, with \s* allowing for zero or more spaces. The entire match is replaced with an empty string, effectively removing these patterns.
    # Replace remaining commas or periods with spaces
    name = re.sub(r'[,.]', ' ', name)#This code replaces any remaining commas or periods in the country name with a single space.This ensures that commas or periods within the name (not caught by the previous step) are converted to spaces for consistency.
    # Normalize multiple spaces
    name = re.sub(r'\s+', ' ', name).strip()#Replaces multiple consecutive spaces with a single space and removes leading/ending spaces.The regex \s+ matches one or more whitespace characters, replacing them with a single space. The strip() method ensures no extra spaces remain at the start or end.
    # Convert to title case
    name = name.title()#This code capitalizes the first letter of every country name. The title() method standardizes the case of the name, making it consistent.
    return name #Returns the cleaned country name which is stored in the DataFrame.
