#Code for NLP analysis
import nltk #Imports the nltk (Natural Language Toolkit) library for NLP tasks.Provides functions like word_tokenize and pos_tag used for linguistic analysis of country names.
from nltk.tokenize import word_tokenize #Imports the word_tokenize function from NLTK for splitting text into words.It is used in n the preprocess_text function to tokenize country names.
from nltk import FreqDist, pos_tag #Imports FreqDist for frequency distribution analysis and pos_tag for part-of-speech tagging.FreqDist is used to count word and POS tag frequencies, while pos_tag assigns grammatical categories to tokens.
from nltk.util import ngrams #Imports the ngrams function to generate sequences of words (bigrams and trigrams). Used to analyze multi-word patterns in country names.
from collections import Counter #Imports the Counter class for counting occurrences of items (e.g., n-grams), which is used to Used to compute the most common bigrams and trigrams.
import numpy as np #Imports the numpy library for numerical operations.it is used indirectly via scipy.stats for correlation calculations and to handle NaN values.
from scipy.stats import pearsonr #Imports the pearsonr function to calculate Pearson correlation coefficients for testing correlations between population density and growth rate, and between area and density.
import re #It imports the re module for regular expression operations for preprocess_text function to remove punctuation from country names.
# Download required NLTK data
try:
    nltk.download('punkt', quiet=True) #Downloads the punkt tokenizer models for word tokenization required for word_tokenize to function correctly.
    nltk.download('averaged_perceptron_tagger', quiet=True) #Downloads the averaged_perceptron_tagger model for POS tagging assign grammatical categories to tokens.
    nltk.download('punkt_tab', quiet=True) # Download the missing resources
    nltk.download('averaged_perceptron_tagger_eng', quiet=True) # Download the missing English POS tagger.
    print("NLTK data downloaded successfully.")#Prints a message confirming that the NLTK data has been downloaded without issues.
except Exception as e:#Catches any unexpected errors that occur during the NLTK data download process.
    print(f"Error downloading NLTK data: {e}")#Prints an error message with details about the exception encountered during the download.
# Load the dataset
try:
    data = pd.read_csv('/content/cleaned_worldbank_country_stats.csv')#Loads the cleaned World Bank dataset from a CSV file into a pandas DataFrame. The dataset contains columns like country, population, growth_rate, density, area, and is_region
    print("Cleaned data loaded successfully.")#Displays cleaned successfully loaded.
except FileNotFoundError:# Catches the specific error that occurs if the file 'cleaned_worldbank_country_stats.csv' does not exist or cannot be found at the specified path.
    print("Error: cleaned_worldbank_country_stats.csv not found.")#Displays if error is found.
    data = pd.DataFrame()#Exit or handle the error appropriately, e.g., set data to an empty DataFrame
if not data.empty: # Check if data is loaded and not empty before proceeding with analysis
    # Function to clean and tokenize country names
    def preprocess_text(text):#Defines a function to clean and tokenize text (country names) for NLP analysis.Prepares text by removing punctuation, converting to lowercase, and tokenizing.
        if not isinstance(text, str):  # Check if the input is a string.
            return []  # Return an empty list if not a string.
        # Remove punctuation and convert to lowercase
        text = re.sub(r'[^\w\s]', ' ', text.lower())#matches non-word, non-space characters, replacing them with spaces. lower() ensures consistency.
        tokens = word_tokenize(text)#Tokenizes the cleaned text into words using NLTK’s word_tokenize. Splits the text into a list of tokens (words).
        return tokens#Returns the list of tokenized output for further analysis.
    # Prepare text data
    country_names = data['country'].tolist()#Extracts the country column as a list of country names for linguistics analysis of country names.
    all_tokens = []#Initializes an empty list to store all tokens from country names for frequency analysis.
    for name in country_names:#Tokenizes each country name and adds the tokens to all_tokens and loops through country names, processes them, and extends the token list.
        processed_name = preprocess_text(name)## Calls the function 'preprocess_text' on the variable 'name' to clean or tokenize the text,returning a processed list of tokens or cleaned string assigned to 'processed_name'.
        all_tokens.extend(processed_name)## Adds the elements of 'processed_name' to the 'all_tokens' list, effectively accumulating all tokens from processed names into one list.
    # Word frequency analysis
    freq_dist = FreqDist(all_tokens)#Creates a frequency distribution of all tokens. This counts how often each word appears across all country names.
    common_words = freq_dist.most_common(10)#Extracsts the 10 most common words from the frequency distribution and stores the top words for linguistic analysis output.
    # N-gram analysis (bigrams and trigrams)
    bigrams = []#Initializes empty lists to store bigrams (2-word sequences)
    trigrams = []#Initializes empty lists to store trigrams (3-word sequences).
    for name in country_names:#Generates bigrams and trigrams for each country name with tokens which checks for non-empty token lists to avoid errors, then uses ngrams to create sequences.
        tokens = preprocess_text(name)## Applies the 'preprocess_text' function to the variable 'name' to clean and tokenize the text,and stores the resulting list of tokens (words) in the variable 'tokens'.
        if tokens: # Only generate ngrams if there are tokens
            bigrams.extend(ngrams(tokens, 2))#Generates all 2-word sequences (bigrams) from the list 'tokens' using the 'ngrams' function, then adds these bigrams to the 'bigrams' list, accumulating all bigram pairs.
            trigrams.extend(ngrams(tokens, 3))#Generates all 2-word sequences (bigrams) from the list 'tokens' using the 'ngrams' function, then adds these bigrams to the 'bigrams' list, accumulating all bigram pairs.
    bigram_freq = Counter(bigrams).most_common(10)#Counts the frequency of bigrams extracting the top 10.
    trigram_freq = Counter(trigrams).most_common(10)#Counts the frequency of trigrams, extracting the top 10.
    # Lexicographical analysis (POS tagging)
    pos_tags = []#Initializes an empty list to store POS-tagged tokens which collects tags for grammatical analysis.
    pos_tagging_skipped = False#Initializes a flag to track if POS tagging is skipped due to errors which is used to note errors in the output DataFrame.
    skipped_countries_pos = [] # To store names of countries skipped during POS tagging
    for name in country_names:#Performs POS tagging on tokens and handles potential errors. Tags tokens with grammatical categories, catching exceptions to avoid crashes. Sets pos_tagging_skipped to True if an error occurs.
        tokens = preprocess_text(name)## Processes the string 'name' through the 'preprocess_text' function, which typically cleans and tokenizes the text, returning a list of tokens stored in 'tokens'.
        if tokens: # Only perform POS tagging if there are tokens
            try:# Starts a try block to catch any exceptions that might occur during POS tagging.
                tagged_tokens = pos_tag(tokens)# Applies part-of-speech (POS) tagging to the list of tokens, assigning a POS tag (like noun, verb, adjective) to each token.The result is a list of (token, tag) tuples stored in 'tagged_tokens'.
                pos_tags.extend(tagged_tokens)# Adds the tagged tokens to the 'pos_tags' list, accumulating all POS-tagged tokens.
            except Exception as e: # Catching a broader exception to be safe
                print(f"Skipping POS tagging for '{name}' (tokens: {tokens}) due to error: {e}")# Prints a message indicating that POS tagging for the current 'name' (with its tokens) was skipped because an error 'e' occurred during the tagging process.
                pos_tagging_skipped = True# Sets a flag variable to True indicating that POS tagging was skipped for at least one entry.
                skipped_countries_pos.append(name)#Adds the current 'name' to a list called 'skipped_countries_pos' to keep track of all names for which POS tagging failed or was skipped.
    pos_freq = Counter(tag for word, tag in pos_tags) if pos_tags else Counter()#Counts the frequency of POS tags, defaulting to an empty Counter if no tags exist. Extracts tags from pos_tags tuples and counts their occurrences.
    # Filter countries (is_region == 0) for cleaner analysis
    countries_only = data[data['is_region'] == 0].copy() # Filters the DataFrame to include only non-regional entities (is_region == 0) and uses .copy() to avoid warnings when modifying the filtered DataFrame.
    if not countries_only.empty: # Check if countries_only is empty before proceeding with hypothesis testing
        # Hypothesis 1: Correlation between population density and growth rate
        # Ensure both columns are numeric and handle potential non-numeric values
        countries_only['density'] = pd.to_numeric(countries_only['density'], errors='coerce')#Converts density columns to numeric types, coercing invalid values to NaN.
        countries_only['growth_rate'] = pd.to_numeric(countries_only['growth_rate'], errors='coerce')#Converts growth_rate columns to numeric types, coercing invalid values to NaN.
        # Drop rows with NaN values after coercion for correlation calculation
        countries_only_cleaned = countries_only.dropna(subset=['density', 'growth_rate'])#Removes rows with NaN in density or growth_rate for correlation analysis.
        if not countries_only_cleaned.empty:# Checks if the DataFrame 'countries_only_cleaned' is not empty meaning it contains data to analyze.
            density_growth_corr, density_growth_p = pearsonr(countries_only_cleaned['density'], countries_only_cleaned['growth_rate'])#Calculates the Pearson correlation coefficient and p-value between the 'density' and 'growth_rate' columns in 'countries_only_cleaned' using the 'pearsonr' function from scipy.stats, 'density_growth_corr' stores the correlation coefficient,and 'density_growth_p' stores the significance p-value.
            hyp1_narrative = f"Hypothesis 1: The correlation between population density and growth rate is {density_growth_corr:.3f} (p-value: {density_growth_p:.3f}). "#Calculates the Pearson correlation and p-value between density and growth_rate if data is available and tests Hypothesis 1 on the relationship between these variables.
            if abs(density_growth_corr) < 0.3:# Checks if the absolute value of the correlation coefficient 'density_growth_corr' is less than 0.3,which typically indicates a weak or negligible linear relationship between the two variables.
                hyp1_narrative += "This weak correlation suggests that high-density countries like 'Malta' (density: 1659.73, growth: 3.83%) and low-density countries like 'Niger' (density: 19.98, growth: 3.28%) show varied growth rates."#Creates a narrative string summarizing the correlation result. The results are formatted to 3dp.
            else:
                hyp1_narrative += f"{'High' if density_growth_corr > 0 else 'Low'} density countries tend to have {'higher' if density_growth_corr > 0 else 'lower'} growth rates."# Updates the string variable 'hyp1_narrative' by appending a sentence describing the relationship between population density and growth rates. It inserts High" or "Low" based on whether the correlation 'density_growth_corr' is positive or negative,and similarly uses "higher" or "lower" to describe growth rates accordingly.
        else:
            hyp1_narrative = "Hypothesis 1: Could not calculate correlation between population density and growth rate due to insufficient valid data."
        # Hypothesis 2: Variability in growth rates for small vs. large populations
        # Ensure population column is numeric before filtering
        countries_only_cleaned['population'] = pd.to_numeric(countries_only_cleaned['population'], errors='coerce')#Converts the 'population' column in the 'countries_only_cleaned' DataFrame to numeric values. Any values that cannot be converted (e.g., invalid strings) are replaced with NaN due to 'errors="coerce"'.
        small_pop = countries_only_cleaned[countries_only_cleaned['population'] < 1000000].copy()#Filters countries into small (<1M)
        large_pop = countries_only_cleaned[countries_only_cleaned['population'] > 100000000].copy()#Filters countries into large (>100M) population groups.
        small_pop['growth_rate'] = pd.to_numeric(small_pop['growth_rate'], errors='coerce')#Ensures growth_rate is numeric in both filtered DataFrames.Redundant since growth_rate was already coerced in countries_only, but ensures robustness.
        large_pop['growth_rate'] = pd.to_numeric(large_pop['growth_rate'], errors='coerce')#Ensures growth_rate is numeric in both filtered DataFrames.Redundant since growth_rate was already coerced in countries_only, but ensures robustness.

        small_var = small_pop['growth_rate'].var() if not small_pop.empty else float('nan')#Calculates the variance of growth_rate for small population countries.Returns NaN if the DataFrames are empty to avoid errors.
        large_var = large_pop['growth_rate'].var() if not large_pop.empty else float('nan')#Calculates the variance of growth_rate for small population countries.Returns NaN if the DataFrames are empty to avoid errors.

        # Check if variances are not NaN before forming the narrative
        if not np.isnan(small_var) and not np.isnan(large_var):
            hyp2_narrative = f"Hypothesis 2: Small-population countries (e.g., 'Tuvalu': population 9646, growth -1.75%) have a growth rate variance of {small_var:.3f}, compared to {large_var:.3f} for large-population countries (e.g., 'India': population 1.45B, growth 0.89%). "
            hyp2_narrative += "Higher variance in small populations indicates more variable growth rates."
        else:
            hyp2_narrative = "Hypothesis 2: Could not calculate variance for small or large population growth rates due to insufficient valid data."
        # Hypothesis 3: Negative growth rates and regional patterns
        negative_growth = countries_only_cleaned[countries_only_cleaned['growth_rate'] < 0].copy()#Filters countries with negative growth rates which identifies countries for regional pattern analysis.
        negative_countries = negative_growth['country'].tolist()#Extracts country names with negative growth rates for linguistic analysis of these countries.
        if negative_countries:
            negative_tokens = [token for name in negative_countries for token in preprocess_text(name)]#Tokenizes country names with negative growth rates for for frequency analysis.
            negative_freq = FreqDist(negative_tokens).most_common(5)#Finds the five most common tokens in negative growth countries for analysis. It identifies common terms for Hypothesis 3.
            hyp3_narrative = f"Hypothesis 3: Countries with negative growth rates include {', '.join(negative_countries[:3])}. "#Creates a narrative for Hypothesis 3, summarizing negative growth countries and their common terms.
            hyp3_narrative += f"Common terms in these names: {negative_freq}. Many are associated with Europe (e.g., 'Albania,' 'Moldova'), suggesting a regional pattern."
        else:
            hyp3_narrative = "Hypothesis 3: No countries with negative growth rates found in the cleaned data."
        # Hypothesis 4: Relationship between land area and population density
        # Ensure area column is numeric
        countries_only_cleaned_area_density = countries_only_cleaned.dropna(subset=['area', 'density'])#Removes rows with NaN in area or density for correlation analysis.
        #Tests the correlation between area and density, creating a narrative.
        if not countries_only_cleaned_area_density.empty:
            area_density_corr, area_density_p = pearsonr(countries_only_cleaned_area_density['area'], countries_only_cleaned_area_density['density'])# Calculates the Pearson correlation coefficient and p-value between the 'area' and 'density' columns in the DataFrame 'countries_only_cleaned_area_density' using the 'pearsonr' function.'area_density_corr' stores the correlation coefficient indicating the strength and direction of the relationship, while 'area_density_p' stores the p-value indicating the statistical significance of the correlation.
            hyp4_narrative = f"Hypothesis 4: The correlation between land area and population density is {area_density_corr:.3f} (p-value: {area_density_p:.3f}). "
            hyp4_narrative += "Regions like 'South Asia' (density: 492.38, area: 3.35M km²) have high density despite moderate area, while 'Sub-Saharan Africa' (density: 51.45, area: 23.89M km²) has low density with large area." # Note: Example countries/regions in the narrative might not directly match the correlation result.
        else:
             hyp4_narrative = "Hypothesis 4: Could not calculate correlation between land area and population density due to insufficient valid data."
        # Hypothesis 5: Characteristics of high-growth countries
        high_growth = countries_only_cleaned[countries_only_cleaned['growth_rate'] > 3].copy()#Filters countries with growth rates above 3% to identify high-growth countries for analysis.
        high_growth_countries = high_growth['country'].tolist()#Extracts names of high-growth countries for the Hypothesis 5 narrative.
        high_growth_stats = high_growth[['population', 'density']].describe()#Computes descriptive statistics for population and density of high-growth countries. Provides mean, std, etc., for Hypothesis 5.
        if not high_growth_stats.empty:#Checking with the high_growth_stats is empty or not.
            # Ensure mean population and density are not NaN before formatting
            mean_population = high_growth_stats['population'].get('mean')# Retrieves the mean (average) value of the 'population' statistic from the 'high_growth_stats' dictionary.
            mean_density = high_growth_stats['density'].get('mean')# Retrieves the mean (average) value of the 'density' statistic from the 'high_growth_stats' dictionary.
            hyp5_narrative = f"Hypothesis 5: High-growth countries (>3% growth rate) include {', '.join(high_growth_countries[:3])}. "#Creates a narrative for Hypothesis 5, summarizing high-growth countries’ characteristics.Uses statistics to describe population and density trends.
            if not pd.isna(mean_population) and not pd.isna(mean_density):
                 hyp5_narrative += f"These countries have a mean population of {mean_population:.0f} and mean density of {mean_density:.2f}, suggesting moderate population sizes and densities."
            else:
                 hyp5_narrative += "Could not calculate mean population and density due to missing data in high-growth countries."
        else:
            hyp5_narrative = "Hypothesis 5: No high-growth countries found in the cleaned data."
    else: # countries_only is empty
        hyp1_narrative = "Hypothesis 1: Could not perform analysis as no non-regional countries were found."
        hyp2_narrative = "Hypothesis 2: Could not perform analysis as no non-regional countries were found."
        hyp3_narrative = "Hypothesis 3: Could not perform analysis as no non-regional countries were found."
        hyp4_narrative = "Hypothesis 4: Could not perform analysis as no non-regional countries were found."
        hyp5_narrative = "Hypothesis 5: Could not perform analysis as no non-regional countries were found."
    # Add 'Type' column to linguistic results
    linguistic_results = pd.DataFrame({#Initializes a pandas DataFrame named linguistic_results to store the results of linguistic analyses performed on the country column of the dataset.
        'Type': ['Linguistic'] * (4 if not pos_tagging_skipped else 3),#Defines the Type column of the linguistic_results DataFrame, labeling each row as a “Linguistic” analysis to distinguish it from hypothesis-related results.
        'Analysis': [#Defines the Analysis column, listing the specific types of linguistic analyses performed (e.g., word frequency, bigrams, trigrams, and optionally POS tag frequency).
            'Word Frequency','Bigram Frequency','Trigram Frequency'] + (['POS Tag Frequency'] if not pos_tagging_skipped else []),
        'Result': [str(common_words), str(bigram_freq),str(trigram_freq)] + ([str(pos_freq.most_common())] if not pos_tagging_skipped else []),#Defines the Result column, containing the actual outputs of the linguistic analyses.
        'Notes': ['', '', ''] + ([''] if not pos_tagging_skipped else ['POS tagging was skipped due to errors.']) })#Defines the Notes column, providing metadata or comments about each linguistic analysis, particularly to flag POS tagging errors.
    #Rename and align hypothesis results
    hypothesis_results = pd.DataFrame({#Initializes a pandas DataFrame named hypothesis_results to store the results of the five hypothesis tests, aligning its structure with linguistic_results for concatenation.
        'Type': ['Hypothesis'] * 5,#Defines the Type column, labeling each row as a “Hypothesis” result to distinguish it from linguistic results.
        'Analysis': [f'Hypothesis {i}' for i in range(1, 6)],#Defines the Analysis column, listing labels for the five hypotheses (e.g., “Hypothesis 1” through “Hypothesis 5”).
        'Result': [#Defines the Result column, containing the textual narratives for each hypothesis test.
            hyp1_narrative,
            hyp2_narrative,
            hyp3_narrative,
            hyp4_narrative,
            hyp5_narrative  ],
        'Notes': [''] * 5})# Add empty Notes column to match structure.
    combined_results = pd.concat([linguistic_results, hypothesis_results], ignore_index=True)# Combine them with aligned columns.
    # Save to CSV
    try:
        combined_results.to_csv('nlp_analysis_results.csv', index=False)# Save the combined results to a CSV file (without row indices)
        print("NLP analysis results saved to 'nlp_analysis_results.csv'")#Displays results in CSV file.
    except IOError as e:#Catches input/output errors that may occur during the file-saving process such as permission issues, disk errors, or file access problems.
        print(f"Error saving NLP analysis results to CSV: {e}")#Prints an error message showing details of the IOError encountered while trying to save the NLP results to a CSV file.
    # Display DataFrames
    display("Linguistic Analysis Results:", linguistic_results)# Display the Linguistic Analysis testing results in the console or notebook
    display("Hypothesis Testing Results:", hypothesis_results)# Display the Hypothesis testing results in the console or notebook
else:
    print("Skipping NLP analysis and hypothesis testing due to empty data.")#Displays if no data is available.